<script setup lang="ts">
import {ref} from 'vue'
import {api,post} from '../api'
import {usePolling} from '../usePolling'
import {number,time} from '../format'
import {shanghaiDate} from '../quantDaily'
import {portfolioState,portfolioGateName,type PortfolioReport} from '../quantPortfolioValidation'
const data=ref<PortfolioReport|null>(null),selected=ref(shanghaiDate()),busy=ref(false),actionError=ref('')
const {error}=usePolling(async signal=>{data.value=await api<PortfolioReport|null>('/api/quant/portfolio-validation',{signal})},60000)
async function generate(){busy.value=true;actionError.value='';try{data.value=await post<PortfolioReport>(`/api/quant/portfolio-validation/run?date=${encodeURIComponent(selected.value)}`)}catch(e){actionError.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
</script>
<template><section class="detail portfolio-validation"><div class="portfolio-heading"><div><h2>组合资金与五仓核验</h2><p>重算保存的真实准入，冻结原账户做一轮内存副本；工程门禁与缺少的现场证据分别列出。</p></div><div class="portfolio-actions"><label>上海日期 <input v-model="selected" type="date" :max="shanghaiDate()"/></label><button class="replay-action" :disabled="busy" @click="generate">{{busy?'冻结及核验中…':'生成当前组合核验'}}</button></div></div>
<p v-if="error||actionError" role="alert" class="radar-notice">{{actionError||error}}</p><p v-if="!data" class="empty">暂无组合核验报告。生成只读取本机已保存资料，不操作原持仓或补下载历史。</p>
<template v-if="data"><p><strong>{{portfolioState(data.status)}}</strong> · 复核日期 {{data.date}}，账户/市场冻结 {{time(data.capturedAt)}}。当前显示最后一次保存结果，不因刷新页面变成新核验。</p>
<div class="portfolio-stats"><div><small>真实复核重算一致</small><strong>{{data.reproduced}}</strong><small>总记录{{data.sourceReviews}} · 其他阶段{{data.notReplayed}} · 缺证据{{data.missingEvidence}} · 不一致{{data.mismatches}}</small></div><div><small>保存准入的最大份额占用</small><strong>{{data.maximumObservedSlots}} / 5</strong><small>包括其他意向；冻结原账户实持{{data.before.positions}}笔</small></div><div><small>合成边界通过 / 未通过</small><strong>{{data.scenariosPassed}} / {{data.scenariosFailed}}</strong><small>未知{{data.scenariosUnknown}} · 不作为现场或盈利样本</small></div><div><small>实际入场的逐次证据</small><strong>{{data.linkedEntries}} / {{data.actualEntries}}</strong><small>缺留档{{data.unlinkedEntries}}笔，不补造早期资料</small></div></div>
<div class="table-scroll"><table><thead><tr><th>核验项</th><th>状态</th><th>范围</th></tr></thead><tbody><tr v-for="gate in data.gates" :key="gate.name"><td>{{portfolioGateName(gate.name)}}</td><td>{{portfolioState(gate.status)}}</td><td>{{gate.detail}}</td></tr></tbody></table></div>
<details><summary>原账户冻结时的资金与额度</summary><p>原账户采样 {{time(data.before.at)}}，实持{{data.before.positions}}笔 / 意向{{data.before.pending}}笔；现金{{number(data.before.cash,6)}}，意向保证金及费预留{{number(data.before.pendingCash,6)}}，剩余可用{{number(data.before.availableCash,6)}} U。原保证金占用{{number(data.before.originalMargin,6)}} U，合计计划风险{{number(data.before.plannedRisk,6)}} U，可信权益{{number(data.before.equity,6)}} U。</p><div class="table-scroll"><table><thead><tr><th>项目</th><th>状态</th><th>上限 / 当前占用</th><th>说明</th></tr></thead><tbody><tr v-for="c in data.before.checks" :key="c.key"><td>{{c.name}}</td><td>{{portfolioState(c.status)}}</td><td>{{number(c.limit,6)}} / {{number(c.after,6)}}</td><td>{{c.reason}}</td></tr></tbody></table></div></details>
<details><summary>冻结原引擎副本的一轮执行</summary><p>重复及反序列化后{{data.repeatable?'输出一致':'输出不一致'}}；源对象{{data.sourcePreserved?'保持':'发生变化'}}。副本产生{{data.copyFills}}条退出、{{data.copyFunding}}条资金费入账、{{data.copyNewPositions}}个新仓。仅内存副本，未提交原账户。</p><p>副本轮次后现金{{number(data.copyAfter.cash,6)}}，剩余可用{{number(data.copyAfter.availableCash,6)}} U；持仓{{data.copyAfter.positions}}、意向{{data.copyAfter.pending}}。这些值不能作为独立账户收益或实际新增成交。</p></details>
<details><summary>真实逐次准入与组合上限 · {{data.rows.length}}条</summary><p v-if="data.rowsLimited">明细仅列最近100条，上方计数使用所选日全部保存记录。</p><details v-for="row in data.rows" :key="row.id"><summary>{{time(row.at)}} · {{row.symbol}} · {{portfolioState(row.outcome)}} · {{portfolioState(row.status)}}</summary><p>{{row.reason}}。原信号{{portfolioState(row.signalStatus)}}。份额{{row.beforeSlots}}→{{row.afterSlots}}，其中已有意向{{row.pendingBefore}}；候选后的可用现金{{number(row.availableAfter,6)}} U。相关性未知{{row.unknownCorrelations}}份，按相关占用。</p><p>计划风险{{number(row.riskBefore,6)}}→{{number(row.riskAfter,6)}} U；原保证金{{number(row.marginBefore,6)}}→{{number(row.marginAfter,6)}} U。</p><div v-if="row.checks.length" class="table-scroll"><table><thead><tr><th>约束</th><th>状态</th><th>上限</th><th>原占用→准入后</th></tr></thead><tbody><tr v-for="c in row.checks" :key="c.key"><td>{{c.name}}<small>{{c.reason}}</small></td><td>{{portfolioState(c.status)}}</td><td>{{number(c.limit,6)}}</td><td>{{number(c.before,6)}}→{{number(c.after,6)}}</td></tr></tbody></table></div><a :href="`/api/quant/entry-review/${row.id}`" target="_blank" rel="noopener">原始复核JSON →</a></details></details>
<details><summary>合成边界案例 · {{data.scenarios.length}}项</summary><p>复用一份冻结真实准入的市场/盘口，修改组合占用、现金或缺失条件。不是五笔实际持仓，不是连续收益回测。</p><div class="table-scroll"><table><thead><tr><th>边界</th><th>预期 / 实际</th><th>核验</th><th>原引擎说明</th></tr></thead><tbody><tr v-for="s in data.scenarios" :key="s.key"><td>{{s.name}}</td><td>{{portfolioState(s.expected)}} / {{portfolioState(s.actual)}}</td><td>{{portfolioState(s.status)}}</td><td>{{s.reason}}</td></tr></tbody></table></div></details>
<details><summary>证据保存与尚未完成的验证</summary><p v-for="limitation in data.limitations" :key="limitation">{{limitation}}</p><p>当前选择{{selected}}仅用于下一次生成；以上报告归属{{data.date}}。冻结输入、原始复核、信号档案及报告单独保存，历史复核和模拟账本不改写。</p><a :href="`/api/quant/portfolio-validation/runs/${data.id}`" target="_blank" rel="noopener">冻结副本及可重放证据JSON →</a><small>{{data.version}} · {{data.inputHash}}</small></details>
</template></section></template>
<style scoped>.portfolio-heading{display:flex;justify-content:space-between;align-items:start;gap:18px;flex-wrap:wrap}.portfolio-heading h2{margin-top:0}.portfolio-actions{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.portfolio-actions label{display:grid;gap:7px;font-size:11px}.portfolio-actions input{color:#b9d0dc;background:#101d27;border:1px solid #334858;padding:7px;border-radius:4px}.portfolio-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.portfolio-stats>div{padding:12px;background:#101b25;border:1px solid #304657;border-radius:6px}.portfolio-stats strong{display:block;font-size:22px;margin:10px 0}.portfolio-validation p{font-size:12px;line-height:1.9}.portfolio-validation small{display:block;color:#91a8b9;overflow-wrap:anywhere}.portfolio-validation details{padding:14px 0;border-top:1px solid #30414d}.portfolio-validation summary{cursor:pointer;font-size:13px}.portfolio-validation td{white-space:normal;min-width:90px}.portfolio-validation td:last-child{min-width:190px}.portfolio-validation a{font-size:12px;color:#8bc3bc}@media(max-width:850px){.portfolio-stats{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:430px){.portfolio-stats{grid-template-columns:1fr}}</style>
